private void removeFromAnythingButsMap(Map<NameState, List<Patterns>> map, NameState nameState, Patterns pattern) {
    List<Patterns> patterns = map.get(nameState);
    if (patterns != null) {
        patterns.remove(pattern);
        if (patterns.isEmpty()) {
            map.remove(nameState);
        }
    }
}
